# Writes ../theme-hook-ledgers.research.json from the facts collected in raw/. No network access.
import json, os, gzip
HERE = os.path.dirname(os.path.abspath(__file__))
S = json.load(open(os.path.join(HERE, 'raw', 'stats.json')))
ALL = [1, 10, 8453, 130, 7777777, 480, 57073, 1868, 42220, 196, 42161, 4663, 99901, 137, 56, 43114, 143, 4326, 4217, 5042, 999]
